scwin.btn_multipleDataListDownload_onclick = function () {
    let fileName = par_fileName.getValue();
    let multipleSheet = par_multipleSheet.getValue();
    let useHeader = par_useHeader.getValue();
    let showProcess = par_showProcess.getValue();
    let freezePane = par_freezePane.getValue();
    let removeColumns = par_removeColumns.getValue();
    let foldColumns = par_foldColumns.getValue();
    let separator = par_separator.getValue();

    let common = {};
    if (fileName !== '') {
        common.fileName = fileName;
    }
    common.multipleSheet = multipleSheet;
    common.showProcess = (showProcess === 'true');
    if (common.showProcess) {
        common.processMsg = "Excel 다운로드 중...";
    }
    if (useHeader !== '') {
        common.useHeader = useHeader;
    }
    if (freezePane !== '') {
        common.freezePane = freezePane;
    }
    if (separator !== '') {
        common.separator = separator;
    }

    let excelInfo = [
        {
            dataListId: "dataList1",
            sheetName: "직원정보",
            removeColumns: removeColumns,
            foldColumns: foldColumns
        },
        {
            dataListId: "dataList2",
            sheetName: "상품정보"
        }
    ];

    let options = {
        common: common,
        excelInfo: excelInfo
    };

    wf_body_bottom.getObj("scwin").setReturnValue("options : " + JSON.stringify(options, null, 2));
    WebSquare.util.multipleDataListDownload(options);
}
